class Gradebook:
    def __init__(self) -> None:
        """Initialize the gradebook."""
        self.assignments = {}
        self.grades = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """Add an assignment to the gradebook.

        Args:
        name (str): The name of the assignment.
        weight (float): The weight of the assignment.
        kind (str): The type of the assignment, either "homework" or "quiz". Defaults to "homework".

        Raises:
        ValueError: If the weight is not a positive number.
        """
        if weight <= 0:
            raise ValueError("Weight must be a positive number")
        if kind not in ["homework", "quiz"]:
            raise ValueError("Kind must be either 'homework' or 'quiz'")
        self.assignments[name] = {"weight": weight, "kind": kind}
        if name not in self.grades:
            self.grades[name] = {}

    def record(self, student: str, assignment: str, grade: float) -> None:
        """Record a grade for a student on an assignment.

        Args:
        student (str): The name of the student.
        assignment (str): The name of the assignment.
        grade (float): The grade of the student on the assignment.

        Raises:
        ValueError: If the grade is not within the range 2.0 to 5.0.
        """
        if grade < 2.0 or grade > 5.0:
            raise ValueError("Grade must be within the range 2.0 to 5.0")
        if assignment not in self.assignments:
            raise ValueError("Assignment does not exist")
        if student not in self.grades[assignment]:
            self.grades[assignment][student] = grade
        else:
            self.grades[assignment][student] = grade

    def average(self, student: str) -> float:
        """Calculate the average grade of a student.

        Args:
        student (str): The name of the student.

        Returns:
        float: The average grade of the student, rounded to two decimal places.
        """
        total_weight = 0
        total_grade = 0
        quiz_grades = []
        for assignment, properties in self.assignments.items():
            if student in self.grades[assignment]:
                grade = self.grades[assignment][student]
            else:
                grade = 2.0
            if properties["kind"] == "quiz":
                quiz_grades.append(grade)
            else:
                total_weight += properties["weight"]
                total_grade += grade * properties["weight"]
        if quiz_grades:
            quiz_grades.sort()
            if len(quiz_grades) > 1:
                quiz_grades = quiz_grades[1:]
            for grade in quiz_grades:
                total_weight += self.assignments[list(self.assignments.keys())[0]]["weight"]
                total_grade += grade * self.assignments[list(self.assignments.keys())[0]]["weight"]
        if total_weight == 0:
            return 0.0
        return round(total_grade / total_weight, 2)
